import{_ as t,o as r,c as n,a5 as o}from"./chunks/framework.DvE3tBec.js";const a="/assets/20180123_134945.CLA110Ns.jpg",m=JSON.parse('{"title":"Second week of intensive collaboration: Jan 22-24, 2018","description":"","frontmatter":{"news":true,"title":"Second week of intensive collaboration: Jan 22-24, 2018","date":"2018-01-31T00:00:00.000Z","author":"Marius Appel","aside":false},"headers":[],"relativePath":"news/2018-01-31-WWU_meeting.md","filePath":"news/2018-01-31-WWU_meeting.md","lastUpdated":1575044769000}'),i={name:"news/2018-01-31-WWU_meeting.md"};function s(p,e,l,c,h,f){return r(),n("div",null,[...e[0]||(e[0]=[o('<p>On Jan 22-24, the <a href="https://www.uni-muenster.de/Geoinformatics/en/index.html" target="_blank" rel="noreferrer">Institute for Geoinformatics</a> at the University of Muenster hosted the <em>second week of intense collaboration</em>. 16 developers from 8 partners worked on implementing the proof of concept use cases for different clients and backends, improving the core API, and connecting the clients to different backends.</p><p>We continued implementing the <a href="https://github.com/Open-EO/openeo-geopyspark-driver" target="_blank" rel="noreferrer">GeoTrellis</a>, <a href="https://github.com/Open-EO/openeo-wcps-driver" target="_blank" rel="noreferrer">WCPS</a>, <a href="https://github.com/Open-EO/openeo-grassgis-driver" target="_blank" rel="noreferrer">GRASS GIS</a>, and <a href="https://github.com/Open-EO/openeo-sentinelhub-driver" target="_blank" rel="noreferrer">Sentinel Hub</a> backend drivers and a <a href="https://github.com/Open-EO/openeo-python-client" target="_blank" rel="noreferrer">Python client</a> for OpenEO, which we started during our <a href="http://openeo.org/openeo/news/2017/12/18/VITO_meeting.html" target="_blank" rel="noreferrer">meeting in December at VITO</a>.</p><p>Besides many improvements in the proof of concept implementations, this week resulted in two more prototypical OpenEO clients:</p><ul><li>A simple browser-based <a href="https://github.com/Open-EO/openeo-js-client" target="_blank" rel="noreferrer">JS client</a> was tested with the <a href="https://github.com/Open-EO/openeo-sentinelhub-driver" target="_blank" rel="noreferrer">Sentinel Hub driver</a> and its implementation of the first proof of concept use case (computing minimum NDVI values over time series of Sentinel 2 data).</li><li>The <a href="https://github.com/Open-EO/openeo-r-client" target="_blank" rel="noreferrer">openeo R package</a> also implements the first use case and demonstrates how R users will communicate with OpenEO backends.</li></ul><p><img src="'+a+'" alt=""></p><p>During the three days, we also discussed important ideas of the core API specification and how it can be improved by supporting synchronous processing and representing descriptions of process chains as resources. <a href="https://www.eodc.eu/" target="_blank" rel="noreferrer">EODC</a> presented its new <a href="https://www.openshift.com/" target="_blank" rel="noreferrer">OpenShift</a>-based architecture to run OpenEO queries in containers. Further important discussions made clear how our proof of concept in month 6 will look like.</p><p>More details of the week&#39;s results can be found in our <a href="https://github.com/Open-EO" target="_blank" rel="noreferrer">GitHub</a> repositories.</p>',7)])])}const u=t(i,[["render",s]]);export{m as __pageData,u as default};
